#include <iostream>

#define SQUARE(x) ((x) * (x))

int main() {
    int a = 5;
    // Replaced with: ((a++) * (a++))
    // Undefined behavior! Modifying 'a' twice in one sequence point.
    int result = SQUARE(a++);

    std::cout << "Result: " << result << ", a: " << a << '\n';
    return 0;
}

#include <iostream>

// Template: generic, type-safe, evaluates arguments ONCE
template <typename T>
T square(T x) {
    return x * x;
}

// constexpr: runs at compile-time if given constants
constexpr int getArraySize() {
    return 10 * 10;
}

int main() {
    int a = 5;
    int result = square(a++); // Safe: a is evaluated once (returns 5), then incremented to 6.

    // Safe to use in places requiring compile-time constants (like array sizes)
    int arr[getArraySize()];

    return 0;
}
